s = open(P, encoding="utf-8").read()
todo = stood = 0
for o, n in PAIRS:
    if s.count(o) == 1 and s.count(n) == 0: todo += 1
    elif s.count(o) == 0 and s.count(n) == 1: stood += 1
    else: sys.exit(f"REFUSED · tools/spelling-bridge-v1.mjs: a replacement's old text occurs {s.count(o)} times and its new text {s.count(n)}; nothing written ({o[:70]!r})")
if not todo:
    print(f"stands already · tools/spelling-bridge-v1.mjs ({stood} of {len(PAIRS)} replacements carried)"); sys.exit(0)
for o, n in PAIRS:
    if s.count(o) == 1 and s.count(n) == 0: s = s.replace(o, n)
open(P, "w", encoding="utf-8").write(s)
